1	/**
2	 * Real-kernel verification of the cgroup resource limits on evaluator commands (v1.1.4 WP-1105 / audit A9).
3	 *
4	 * Every check launches a command through the production evaluator-command runner (`createContainedRunner`, the code
5	 * behind `runArgv` that build and typecheck_clean use) with `resources` set small, and reads the kernel's own
6	 * counters. Nothing here is an injected runner: the only injected seam is a pass-through spy that keeps the
7	 * supervisor's report, which the runner otherwise reduces to status/signal/error.
8	 *
9	 * Skipped, with the reason printed, unless this host can run the contract for real: cgroup v2 with a systemd user
10	 * manager that delegates cpu+memory+pids, Bubblewrap, prlimit, and a dedicated tmpfs in
11	 * NEXUS_EVAL_TEST_WORKSPACE_ROOT (the same fixture `make test-ci` and CI provide). A skip is not verification.
12	 *
13	 * Safety: the supervisor applies and reads back memory.max, pids.max and cpu.max on the payload cgroup BEFORE the
14	 * command starts, and refuses (never runs the command) when it cannot. The hog, the fork bomb and the busy loops only
15	 * ever run inside that cgroup, with a wall-clock timeout.
16	 */
17	import { test } from "node:test";
18	import type { TestContext } from "node:test";
19	import assert from "node:assert/strict";
20	import fs from "node:fs";
21	import os from "node:os";
22	import path from "node:path";
23	import { randomUUID } from "node:crypto";
24	import { spawnSync } from "node:child_process";
25	import { fileURLToPath } from "node:url";
26	
27	const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
28	const MIB = 1024 * 1024;
29	const uid = process.getuid!();
30	const USER_SERVICE = `/sys/fs/cgroup/user.slice/user-${uid}.slice/user@${uid}.service`;
31	const APP_SLICE = path.join(USER_SERVICE, "app.slice");
32	
33	/** memory.peak (kernel 5.19) and pids.peak (6.1) may be absent: the peak bounds are then reported as not checked, not failed. */
34	const PEAKS = fs.existsSync(path.join(USER_SERVICE, "memory.peak")) && fs.existsSync(path.join(USER_SERVICE, "pids.peak"));
35	
36	type Final = Record<string, any>;
37	type Run = { result: any; final: Final | undefined; sampled: Sampled; marker: string; ms: number; before: Set<string> };
38	type Sampled = { scopes: string[]; raw: Record<string, string> };
39	
40	const read = (file: string) => { try { return fs.readFileSync(file, "utf8"); } catch { return null; } };
41	const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
42	
43	/** Why this host cannot verify the contract for real, or null. Computed once; the probe is a harmless `true` in a scope. */
44	let gate: Promise<{ reason: string | null; resources?: any }> | undefined;
45	function hostGate() {
46	  gate ??= (async () => {
47	    if (process.platform !== "linux") return { reason: "not Linux" };
48	    if (!fs.existsSync("/sys/fs/cgroup/cgroup.controllers")) return { reason: "no cgroup v2 unified hierarchy at /sys/fs/cgroup" };
49	    if (!fs.existsSync(path.join(USER_SERVICE, "cgroup.kill"))) return { reason: "this kernel has no cgroup.kill (before 5.14): the harness could not stop a fork bomb" };
50	    const delegated = read(path.join(USER_SERVICE, "cgroup.controllers"))?.trim().split(/\s+/) ?? [];
51	    for (const controller of ["cpu", "memory", "pids"]) {
52	      if (!delegated.includes(controller)) return { reason: `the systemd user manager does not delegate the ${controller} controller (${USER_SERVICE}/cgroup.controllers: "${delegated.join(" ")}")` };
53	    }
54	    if (!fs.existsSync("/usr/bin/pgrep")) return { reason: "pgrep is unavailable" };
55	    if (!process.env.XDG_RUNTIME_DIR) return { reason: "XDG_RUNTIME_DIR is unset: no systemd user manager session" };
56	    const workspaceRoot = process.env.NEXUS_EVAL_TEST_WORKSPACE_ROOT;
57	    if (!workspaceRoot) return { reason: "NEXUS_EVAL_TEST_WORKSPACE_ROOT is unset: no dedicated capped tmpfs for the resource contract (run `make test-ci`)" };
58	    const { resourceProbeProblem } = await import(path.join(ROOT, "eval/resources.mjs"));
59	    const { sandboxAvailable } = await import(path.join(ROOT, "eval/isolate.mjs"));
60	    if (!sandboxAvailable()) return { reason: "Bubblewrap is unavailable or cannot start here" };
61	    if (!fs.existsSync("/usr/bin/prlimit")) return { reason: "prlimit is unavailable" };
62	    const tmpfs = fs.statfsSync(workspaceRoot);
63	    const resources = { cpuPercent: 50, memoryBytes: 64 * MIB, tasks: 16, storageBytes: tmpfs.blocks * tmpfs.bsize, workspaceRoot };
64	    const problem = resourceProbeProblem(resources);
65	    if (problem) return { reason: `the resource contract probe fails on this host: ${problem}` };
66	    return { reason: null, resources };
67	  })();
68	  return gate;
69	}
