71	/** The resources to use. Without the fixtures: skip with the reason and return null. With them set (CI, `make test-ci`): fail, as eval_integrity does, so a lost delegation cannot turn this file green by skipping. */
72	async function requireHost(t: TestContext) {
73	  const { reason, resources } = await hostGate();
74	  if (reason && process.env.NEXUS_EVAL_TEST_WORKSPACE_ROOT) assert.fail(`the CI evaluator fixtures are configured (NEXUS_EVAL_TEST_WORKSPACE_ROOT is set) but the cgroup contract cannot run: ${reason}`);
75	  if (reason) { t.skip(`cannot verify cgroup limits on this host: ${reason}`); return null; }
