79	/** Scope cgroups (under the user manager) whose payload leaf holds a process whose command line contains `marker`. */
80	function scopesHolding(marker: string) {
81	  const found: string[] = [];
82	  let entries: string[] = [];
83	  try { entries = fs.readdirSync(APP_SLICE); } catch { return found; }
84	  for (const entry of entries) {
85	    if (!entry.startsWith("run-") || !entry.endsWith(".scope")) continue;
86	    const procs = read(path.join(APP_SLICE, entry, "payload", "cgroup.procs"));
87	    if (!procs) continue;
88	    for (const pid of procs.split("\n").filter(Boolean)) {
89	      if ((read(`/proc/${pid}/cmdline`) ?? "").includes(marker)) { found.push(path.join(APP_SLICE, entry)); break; }
90	    }
91	  }
92	  return found;
93	}
94	
95	/** Names of the transient scopes under the user manager right now (the slice may not exist: then none). */
96	function listScopes(): Set<string> {
97	  try { return new Set(fs.readdirSync(APP_SLICE).filter((e) => e.startsWith("run-") && e.endsWith(".scope"))); } catch { return new Set(); }
98	}
99	
100	/** Poll the cgroup files of this run's scope while it lives, as raw evidence next to the supervisor's report (informational: a short run can end between ticks). */
101	function startSampler(marker: string): { stop: () => Sampled } {
102	  const scopes = new Set<string>();
103	  const raw: Record<string, string> = {};
104	  const timer = setInterval(() => {
105	    for (const scope of scopesHolding(marker)) {
106	      scopes.add(scope);
107	      for (const file of ["memory.events", "pids.events", "cpu.stat", "memory.max", "pids.max", "cpu.max", "memory.swap.max", "memory.oom.group"]) {
108	        const text = read(path.join(scope, "payload", file));
109	        if (text !== null) raw[file] = text.trim();
110	      }
111	    }
112	  }, 15);
113	  return { stop: () => { clearInterval(timer); return { scopes: [...scopes], raw }; } };
114	}
