116	async function launch(resources: any, command: string, args: string[], timeoutMs: number, opts: { env?: Record<string, string | undefined>; cwd?: string } = {}): Promise<Run> {
117	  const { createContainedRunner } = await import(path.join(ROOT, "eval/evaluators/code/command.mjs"));
118	  const { runIsolatedProcess } = await import(path.join(ROOT, "eval/isolate.mjs"));
119	  let final: Final | undefined;
120	  const runner = createContainedRunner({
121	    runIsolatedProcess: async (spec: any, options: any) => { const outcome = await runIsolatedProcess(spec, options); final = outcome.resources; return outcome; },
122	  });
123	  const marker = `nexus-a9-${randomUUID()}`;
124	  const cwd = opts.cwd ?? fs.mkdtempSync(path.join(resources.workspaceRoot, "a9-cgroup-"));
125	  const saved: Record<string, string | undefined> = {};
126	  for (const [key, value] of Object.entries(opts.env ?? {})) { saved[key] = process.env[key]; if (value === undefined) delete process.env[key]; else process.env[key] = value; }
127	  const before = listScopes();
128	  const sampler = startSampler(marker);
129	  const started = Date.now();
130	  try {
131	    const result = await runner(command, [...args, marker], { cwd, timeoutMs, resources });
132	    const ms = Date.now() - started;
133	    return { result, final, sampled: sampler.stop(), marker, ms, before };
134	  } finally {
135	    sampler.stop();
136	    for (const [key, value] of Object.entries(saved)) { if (value === undefined) delete process.env[key]; else process.env[key] = value; }
137	    if (!opts.cwd) fs.rmSync(cwd, { recursive: true, force: true });
138	  }
139	}
