141	/** The shell script runs as `sh -c <script> <marker>`: `$0` carries the marker into every process's argv. */
142	const sh = (resources: any, script: string, timeoutMs: number, opts = {}) => launch(resources, "/bin/sh", ["-c", script], timeoutMs, opts);
143	
144	/**
145	 * Nothing of this run is left: every scope that appeared since the run started is gone, or is some other run's live scope
146	 * (populated by processes that do not carry this run's marker). An unpopulated new scope, or one still holding this
147	 * run's marker, is a leftover. Scopes the sampler saw must also be gone. No process carrying the marker survives.
148	 */
149	async function assertCleanedUp(run: Run) {
150	  const leftovers = () => {
151	    const out: string[] = [];
152	    for (const name of listScopes()) {
153	      if (run.before.has(name)) continue;
154	      const dir = path.join(APP_SLICE, name);
155	      const populated = !/^populated 0$/m.test(read(path.join(dir, "cgroup.events")) ?? "populated 0");
156	      if (!populated || scopesHolding(run.marker).includes(dir)) out.push(dir);
157	    }
158	    for (const dir of run.sampled.scopes) if (fs.existsSync(dir) && !out.includes(dir)) out.push(dir);
159	    return out;
160	  };
161	  const deadline = Date.now() + 8000;
162	  let leftover = leftovers();
163	  while (leftover.length && Date.now() < deadline) { await sleep(100); leftover = leftovers(); }
164	  for (const scope of leftover) { try { fs.writeFileSync(path.join(scope, "cgroup.kill"), "1"); } catch {} }
165	  assert.deepEqual(leftover, [], "a transient scope cgroup outlived its command");
166	  const pgrep = spawnSync("/usr/bin/pgrep", ["-f", run.marker], { encoding: "utf8" });
167	  assert.equal(pgrep.status, 1, `a process carrying the run marker survived: ${pgrep.stdout}`);
168	  assert.equal(run.final?.cleaned, true, JSON.stringify(run.final));
169	}
