81	  if (configProblem) return configProblem;
82	  let wrapped;
83	  try { wrapped = containedSpec({ cmd: "/usr/bin/true", argv: [] }, resources); }
84	  catch (error) { return error.message; }
85	  // The supervisor always opens fd 4 as its control channel, even when a probe never sends a
86	  // signal. Keep the descriptor present so preflight exercises the same supervisor contract as
87	  // spawnContained rather than failing before the resource check can report its result.
88	  const result = spawnSync(wrapped.cmd, wrapped.argv, { cwd: "/", env: wrapped.env, stdio: ["ignore", "ignore", "pipe", "pipe", "pipe"], timeout: 15_000, encoding: "utf8" });
